            rec.append(ct + 1)

            if rec[-1] > n1:
                return (len(rec) - 2) // n2

            if start not in track:
                track[start] = len(rec) - 1
            else:
                break

        cycle_start_s1 = rec[track[start]]
        cycle_s1 = (ct + 1) - cycle_start_s1
        cycle_s2 = (len(rec) - 1) - track[start]
        rest_s1 = n1 - cycle_start_s1

