from typing import List
from functools import lru_cache

class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        MOD = 1_000_000_007
        self.r = len(pizza)
        self.c = len(pizza[0])

        # build suffix sum of apples: apples in sub-rectangle (i,j) -> (r-1,c-1)
        self.suf = [[0] * (self.c + 1) for _ in range(self.r + 1)]
        for i in range(self.r - 1, -1, -1):
            for j in range(self.c - 1, -1, -1):
                self.suf[i][j] = (
                    self.suf[i + 1][j] + self.suf[i][j + 1] - self.suf[i + 1][j + 1] + (pizza[i][j] == "A")
                )

        if self.suf[0][0] < k:
            return 0
        return self.getWays(0, 0, k) % MOD

    @lru_cache(None)
    def getWays(self, i: int, j: int, k: int) -> int:
        MOD = 1_000_000_007
        if self.suf[i][j] == 0:
            return 0
        if k == 1:
            return 1

        res = 0
        # horizontal cuts
        for nr in range(i + 1, self.r):
            if self.suf[i][j] - self.suf[nr][j] > 0:  # top has apple
                res = (res + self.getWays(nr, j, k - 1)) % MOD
        # vertical cuts
        for nc in range(j + 1, self.c):
            if self.suf[i][j] - self.suf[i][nc] > 0:  # left has apple
                res = (res + self.getWays(i, nc, k - 1)) % MOD

        return res

