class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        if n1 == 0:
            return 0
        if not set(s2).issubset(set(s1)):
            return 0

        rec, track = [0], defaultdict(int)
        ct = start = ptr = 0

        while True:
            for ch in s2:
                pos = s1.find(ch, start)
                if pos == -1:
                    ct += 1
                    pos = s1.find(ch)
                    start = 0
                start = pos + 1
                ptr = pos

            rec.append(ct + 1)

            if rec[-1] >= n1:
                return (len(rec) - 2) // n2

            if ptr not in track:
                track[ptr] = len(rec) - 1
            else:
                break

        cycleStart = rec[track[ptr]]
        cycle1 = (ct + 1) - cycleStart
        cycle2 = (len(rec) - 1) - track[ptr]
        rest = n1 - cycleStart
        rem = cycleStart + rest % cycle1

        ptr2 = 1
        while ptr2 < len(rec) and rec[ptr2] <= rem:
            ptr2 += 1

        return (cycle2 * (rest // cycle1) + ptr2 - 2) // n2

