class Solution:
    def construct(self, grid: List[List[int]]) -> 'Node':
        n = len(grid)
        return self.buildTree(grid, 0, n, 0, n, n) if n else None

    def buildTree(self, grid: List[List[int]], rs: int, re: int, cs: int, ce: int, level: int) -> 'Node':
        if level == 1:
            return Node(bool(grid[rs][cs]), True, None, None, None, None)

        half = level // 2
        tl = self.buildTree(grid, rs, rs + half, cs, cs + half, half)
        tr = self.buildTree(grid, rs, rs + half, cs + half, ce, half)
        bl = self.buildTree(grid, rs + half, re, cs, cs + half, half)
        br = self.buildTree(grid, rs + half, re, cs + half, ce, half)

        if tl.isLeaf and tr.isLeaf and bl.isLeaf and br.isLeaf and tl.val == tr.val == bl.val == br.val:
            return Node(tl.val, True, None, None, None, None)
        return Node(False, False, tl, tr, bl, br)

class Solution:
    def smallestString(self, s: str) -> str:
        # If all characters are the same
        if len(set(s)) == 1:
            return s[:-1] + 'z' if s != "a" * len(s) else s

        contiguous, change, ct1, ct2 = True, False, 0, 0

        # Count leading 'a's
        for ch in s:
            if ch == 'a':
                ct1 += 1
            else:
                break

        ans = 'a' * ct1
        s = s[ct1:]

        for cha in s:
            ct2 += 1
            if cha != 'a':
                ans += chr(ord(cha) - 1)
                change = True
            else:
                ans += cha
                if change:
                    contiguous = False
            if not contiguous:
                break

        return ans + s[ct2:] if change else ans[:-1] + 'z'

