class Solution:
    def maxPower(self, stations: List[int], r: int, k: int) -> int:
        start, end = 0, sum(stations) + k
        while start + 1 < end:
            mid = (start + end) // 2
            if self.check(stations[:], r, k, mid):
                start = mid
            else:
                end = mid
        return end if self.check(stations[:], r, k, end) else start

    def check(self, stations, r, k, target):
        n = len(stations)
        newStations = defaultdict(int)
        power = sum(stations[:r])
        for i in range(n):
            if i + r < n:
                power += stations[i + r]
            if i - r - 1 >= 0:
                power -= stations[i - r - 1]
            if power < target:
                diff = target - power
                if diff > k:
