from typing import List
from functools import lru_cache

MOD = 10**9 + 7

class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        self.r = len(pizza)
        self.c = len(pizza[0])

        # suffix apples count: apples in sub-rectangle (i,j) -> (r-1,c-1)
        apples = [[0] * (self.c + 1) for _ in range(self.r + 1)]
        for i in range(self.r - 1, -1, -1):
            for j in range(self.c - 1, -1, -1):
                apples[i][j] = (apples[i + 1][j] + apples[i][j + 1] - apples[i + 1][j + 1]
                                + (1 if pizza[i][j] == 'A' else 0))

        if apples[0][0] < k:
            return 0

        @lru_cache(None)
        def dp(i: int, j: int, cuts_left: int) -> int:
            if apples[i][j] == 0:
                return 0
            if cuts_left == 0:
                return 1

            res = 0
            # horizontal cut: top part must have apple => apples[i][j] - apples[nr][j] > 0
            for nr in range(i + 1, self.r):
                if apples[i][j] - apples[nr][j] > 0:
                    res = (res + dp(nr, j, cuts_left - 1)) % MOD

            # vertical cut: left part must have apple => apples[i][j] - apples[i][nc] > 0
            for nc in range(j + 1, self.c):
                if apples[i][j] - apples[i][nc] > 0:
                    res = (res + dp(i, nc, cuts_left - 1)) % MOD

            return res

        return dp(0, 0, k - 1)

