from typing import List, Optional

class Node:
    __slots__ = ("val", "prio", "cnt", "size", "left", "right")
    def __init__(self, val: int, prio: int):
        self.val = val
        self.prio = prio
        self.cnt = 1
        self.size = 1
        self.left: Optional["Node"] = None
        self.right: Optional["Node"] = None

def _sz(t: Optional[Node]) -> int:
    return t.size if t else 0

def _upd(t: Node) -> None:
    t.size = t.cnt + _sz(t.left) + _sz(t.right)

def _rot_r(t: Node) -> Node:
    l = t.left
    t.left = l.right
    l.right = t
    _upd(t); _upd(l)
    return l

def _rot_l(t: Node) -> Node:
    r = t.right
    t.right = r.left
    r.left = t
    _upd(t); _upd(r)
    return r

def insert(t: Optional[Node], x: int) -> Node:
    import random
    if not t:
        return Node(x, random.randint(1, 1_000_000_000))
    if x == t.val:
        t.cnt += 1
    elif x < t.val:
        t.left = insert(t.left, x)
        if t.left.prio < t.prio:
            t = _rot_r(t)
    else:
        t.right = insert(t.right, x)
        if t.right.prio < t.prio:
            t = _rot_l(t)
    _upd(t)
    return t

def remove(t: Optional[Node], x: int) -> Optional[Node]:
    if not t:
        return None
    if x == t.val:
        if t.cnt > 1:
            t.cnt -= 1
        else:
            if not t.left:
                return t.right
            if not t.right:
                return t.left
            if t.left.prio < t.right.prio:
                t = _rot_r(t)
                t.right = remove(t.right, x)
            else:
                t = _rot_l(t)
                t.left = remove(t.left, x)
    elif x < t.val:
        t.left = remove(t.left, x)
    else:
        t.right = remove(t.right, x)
    _upd(t)
    return t

def size(t: Optional[Node]) -> int:
    return _sz(t)

def get(t: Node, k: int) -> int:  # 1-indexed
    left = _sz(t.left)
    if k <= left:
        return get(t.left, k)
    if k <= left + t.cnt:
        return t.val
    return get(t.right, k - left - t.cnt)

