class Solution:
    def construct(self, grid: List[List[int]]) -> 'Node':
        n = len(grid)
        return self.buildTree(grid, 0, n, 0, n) if n else None

    def buildTree(self, grid, rs, re, cs, ce):
        if re - rs == 1:
            return Node(grid[rs][cs] == 1, True, None, None, None, None)

        midr = (rs + re) // 2
        midc = (cs + ce) // 2
        tl = self.buildTree(grid, rs, midr, cs, midc)
        tr = self.buildTree(grid, rs, midr, midc, ce)
