from typing import List, Optional

class Node:
    __slots__ = ("val", "prio", "cnt", "size", "left", "right")
    def __init__(self, val: int, prio: int):
        self.val = val
        self.prio = prio
        self.cnt = 1
        self.size = 1
        self.left: Optional["Node"] = None
        self.right: Optional["Node"] = None

def size(t: Optional[Node]) -> int:
    return t.size if t else 0

def upd(t: Optional[Node]) -> None:
    if t:
        t.size = t.cnt + size(t.left) + size(t.right)

def rot_right(p: Node) -> Node:
    q = p.left
    p.left = q.right
    q.right = p
    upd(p); upd(q)
    return q

def rot_left(p: Node) -> Node:
    q = p.right
    p.right = q.left
    q.left = p
    upd(p); upd(q)
    return q

def insert(t: Optional[Node], x: int) -> Node:
    import random
    if not t:
        return Node(x, random.randint(1, 1_000_000_000))
    if x == t.val:
        t.cnt += 1
    elif x < t.val:
        t.left = insert(t.left, x)
        if t.left.prio < t.prio:
            t = rot_right(t)
    else:
        t.right = insert(t.right, x)
        if t.right.prio < t.prio:
            t = rot_left(t)
    upd(t)
    return t

def merge(a: Optional[Node], b: Optional[Node]) -> Optional[Node]:
    if not a or not b:
        return a or b
    if a.prio < b.prio:
        a.right = merge(a.right, b)
        upd(a)
        return a
    else:
        b.left = merge(a, b.left)
        upd(b)
        return b

def remove(t: Optional[Node], x: int) -> Optional[Node]:
    if not t:
        return None
    if x == t.val:
        if t.cnt > 1:
            t.cnt -= 1
        else:
            return merge(t.left, t.right)
    elif x < t.val:
        t.left = remove(t.left, x)
    else:
        t.right = remove(t.right, x)
    upd(t)
    return t

def get(t: Node, k: int) -> int:
    left_sz = size(t.left)
    if k <= left_sz:
        return get(t.left, k)
    if k <= left_sz + t.cnt:
        return t.val
    return get(t.right, k - left_sz - t.cnt)

