from typing import List
from functools import cache

MOD = 1_000_000_007


class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        self.r = len(pizza)
        self.c = len(pizza[0])

        # suffix sum of apples: apples in sub-rectangle (i..r-1, j..c-1)
        self.suf = [[0] * (self.c + 1) for _ in range(self.r + 1)]
        for i in range(self.r - 1, -1, -1):
            for j in range(self.c - 1, -1, -1):
                self.suf[i][j] = (
                    self.suf[i + 1][j]
                    + self.suf[i][j + 1]
                    - self.suf[i + 1][j + 1]
                    + (1 if pizza[i][j] == "A" else 0)
                )

        if self.suf[0][0] < k:
            return 0
        if k == 1:
            return 1
        return self.getWays(0, 0, k) % MOD

    @cache
    def getWays(self, i: int, j: int, k: int) -> int:
        if self.suf[i][j] == 0:
            return 0
        if k == 1:
            return 1

        ans = 0
        # horizontal cuts
        for nr in range(i + 1, self.r):
            if self.suf[i][j] - self.suf[nr][j] > 0:
                ans += self.getWays(nr, j, k - 1)
        # vertical cuts
        for nc in range(j + 1, self.c):
            if self.suf[i][j] - self.suf[i][nc] > 0:
                ans += self.getWays(i, nc, k - 1)

        return ans % MOD

