class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        if n1 == 0:
            return 0
        if not set(s2).issubset(set(s1)):
            return 0

        track = {}
        rec = []
        index2 = count2 = 0

        for k in range(1, n1 + 1):
            for ch in s1:
                if ch == s2[index2]:
                    index2 += 1
                    if index2 == len(s2):
                        index2 = 0
                        count2 += 1

            if index2 in track:
                k0, c0 = track[index2]
                pre_loop_k, pre_loop_c = k0, c0
                in_loop_k, in_loop_c = k - k0, count2 - c0

                remaining = n1 - pre_loop_k
                loops = remaining // in_loop_k
                total = pre_loop_c + loops * in_loop_c

                rest = remaining % in_loop_k
                index2_rest, c_rest = 0, 0
                for _ in range(rest):
                    for ch in s1:
                        if ch == s2[index2_rest]:
                            index2_rest += 1
                            if index2_rest == len(s2):
                                index2_rest = 0
                                c_rest += 1
                total += c_rest
                return total // n2

            track[index2] = (k, count2)

        return count2 // n2

