class Solution:
    def findAllRecipes(self, recepies: List[str], ingredients: List[List[str]], supplies: List[str]) -> List[str]:
        dct = defaultdict(list)
        indegree = {}
        n = len(recepies)

        for r in recepies:
            indegree[r] = 0

        for i in range(n):
            for ing in ingredients[i]:
                indegree.setdefault(ing, 0)

        for i in range(n):
            for ing in ingredients[i]:
                dct[ing].append(recepies[i])
                indegree[recepies[i]] += 1

        st = deque()
        for node, deg in indegree.items():
            if deg == 0:
                st.append(node)

        flst = []
        ans = defaultdict(list)

        while st:
            x = st.popleft()
            for r in dct[x]:
                for dep in ans[x]:
                    if dep not in ans[r]:
