from typing import List

class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        trie = {}
        for f in forbidden:
            t = trie
            for c in f:
                t = t.setdefault(c, {})
            t["end"] = True

        def forbidden_len(s: str):
            t = trie
            counter = 0
            for c in s:
                if c not in t:
                    return None
                t = t[c]
                counter += 1
                if "end" in t:
                    return counter
            return None

        res = 0
        j = len(word)
        for i in range(len(word) - 1, -1, -1):
            hit = forbidden_len(word[i:j])
            if hit is not None:
                j = i + hit - 1
            res = max(res, j - i)
        return res

